const item = $input.first().json;

const candidateName = item.candidate_name || "Candidato";
const candidateEmail = item.candidate_email;
const jobTitle = item.job_title || "Vacante";
const scheduledAt = item.scheduled_at;
const durationMin = item.duration_minutes || 60;
const meetingUrl = item.meeting_url;
const interviewer = item.interviewer || "Equipo de Recruitment";

const date = new Date(scheduledAt);
const weekday = date.toLocaleDateString("es-ES", { weekday: "long" });
const day = date.getDate();
const month = date.toLocaleDateString("es-ES", { month: "long" });
const year = date.getFullYear();
const time = date.toLocaleTimeString("es-ES", { hour: "2-digit", minute: "2-digit" });

const formattedDate = weekday.charAt(0).toUpperCase() + weekday.slice(1) + ", " + day + " de " + month + " de " + year;
const formattedTime = time + " (" + durationMin + " min)";

var html = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"></head><body style=\"font-family:Segoe UI,Arial,sans-serif;background:#f4f4f8;margin:0;padding:0;\">";
html += "<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f4f4f8;padding:40px 20px;\"><tr><td align=\"center\">";
html += "<table width=\"560\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);\">";
html += "<tr><td style=\"background:linear-gradient(135deg,#7c3aed,#a855f7);padding:32px 40px;text-align:center;\"><h1 style=\"color:#fff;font-size:22px;margin:0;font-weight:700;\">Invitación a Entrevista</h1></td></tr>";
html += "<tr><td style=\"padding:32px 40px;\">";
html += "<p style=\"color:#1e293b;font-size:16px;line-height:1.6;margin:0 0 20px 0;\">Hola <strong>" + candidateName + "</strong>,</p>";
html += "<p style=\"color:#475569;font-size:15px;line-height:1.6;margin:0 0 24px 0;\">Nos complace invitarte a una entrevista para el puesto de <strong>" + jobTitle + "</strong>.</p>";
html += "<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f8fafc;border-radius:12px;border:1px solid #e2e8f0;margin-bottom:24px;\"><tr><td style=\"padding:20px 24px;\">";
html += "<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">";
html += "<tr><td style=\"padding-bottom:12px;\"><span style=\"color:#64748b;font-size:12px;text-transform:uppercase;font-weight:600;\">Puesto</span><p style=\"color:#1e293b;font-size:15px;font-weight:600;margin:4px 0 0 0;\">" + jobTitle + "</p></td></tr>";
html += "<tr><td style=\"padding-bottom:12px;\"><span style=\"color:#64748b;font-size:12px;text-transform:uppercase;font-weight:600;\">Fecha</span><p style=\"color:#1e293b;font-size:15px;font-weight:600;margin:4px 0 0 0;\">" + formattedDate + "</p></td></tr>";
html += "<tr><td style=\"padding-bottom:12px;\"><span style=\"color:#64748b;font-size:12px;text-transform:uppercase;font-weight:600;\">Hora</span><p style=\"color:#1e293b;font-size:15px;font-weight:600;margin:4px 0 0 0;\">" + formattedTime + "</p></td></tr>";
html += "<tr><td style=\"padding-bottom:12px;\"><span style=\"color:#64748b;font-size:12px;text-transform:uppercase;font-weight:600;\">Entrevistador</span><p style=\"color:#1e293b;font-size:15px;font-weight:600;margin:4px 0 0 0;\">" + interviewer + "</p></td></tr>";
html += "<tr><td><span style=\"color:#64748b;font-size:12px;text-transform:uppercase;font-weight:600;\">Enlace</span><p style=\"margin:6px 0 0 0;\"><a href=\"" + meetingUrl + "\" style=\"display:inline-block;background:#7c3aed;color:#fff;padding:10px 24px;border-radius:8px;text-decoration:none;font-size:14px;font-weight:600;\">Unirse a la reunión</a></p></td></tr>";
html += "</table></td></tr></table>";
html += "<p style=\"color:#475569;font-size:14px;line-height:1.6;margin:0 0 8px 0;\">Por favor, confirma tu asistencia respondiendo a este correo.</p>";
html += "<p style=\"color:#94a3b8;font-size:13px;line-height:1.6;margin:0;\">Saludos cordiales,<br><strong>Equipo de Recruitment</strong></p>";
html += "</td></tr>";
html += "<tr><td style=\"background:#f8fafc;padding:20px 40px;text-align:center;border-top:1px solid #e2e8f0;\"><p style=\"color:#94a3b8;font-size:12px;margin:0;\">AI Recruitment Platform &mdash; Este es un mensaje automático.</p></td></tr>";
html += "</table></td></tr></table></body></html>";

return [{
  json: {
    to: candidateEmail,
    subject: "Invitación a Entrevista - " + jobTitle,
    html: html
  }
}];
